import Axis = require( './index' );


// TESTS //

// The function returns an axis instance...
{
	new Axis( { 'scale': 'xScale', 'orient': 'bottom' } ); // $ExpectType Axis
	new Axis( { 'scale': 'xScale', 'orient': 'bottom', 'title': 'x' } ); // $ExpectType Axis
	new Axis( { 'scale': 'xScale', 'orient': 'bottom', 'title': 'x', 'grid': true, 'labelAngle': 45 } ); // $ExpectType Axis

	Axis( { 'scale': 'xScale', 'orient': 'bottom' } ); // $ExpectType Axis
	Axis( { 'scale': 'xScale', 'orient': 'bottom', 'title': 'x' } ); // $ExpectType Axis
	Axis( { 'scale': 'xScale', 'orient': 'bottom', 'title': 'x', 'grid': true, 'labelAngle': 45 } ); // $ExpectType Axis
}

// The compiler throws an error if the function is not provided an options argument...
{
	new Axis(); // $ExpectError
	Axis(); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	new Axis( '5' ); // $ExpectError
	new Axis( 5 ); // $ExpectError
	new Axis( true ); // $ExpectError
	new Axis( false ); // $ExpectError
	new Axis( null ); // $ExpectError
	new Axis( [] ); // $ExpectError
	new Axis( ( x: number ): number => x ); // $ExpectError

	Axis( '5' ); // $ExpectError
	Axis( 5 ); // $ExpectError
	Axis( true ); // $ExpectError
	Axis( false ); // $ExpectError
	Axis( null ); // $ExpectError
	Axis( [] ); // $ExpectError
	Axis( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which does not specify an axis scale and orientation...
{
	new Axis( {} ); // $ExpectError
	new Axis( { 'scale': 'xScale' } ); // $ExpectError
	new Axis( { 'orient': 'bottom' } ); // $ExpectError

	Axis( {} ); // $ExpectError
	Axis( { 'scale': 'xScale' } ); // $ExpectError
	Axis( { 'orient': 'bottom' } ); // $ExpectError
}

